'use client';
const require_error_summary = require("./error-summary.cjs");
const require_error_summary_heading = require("./error-summary-heading.cjs");
const require_error_summary_item = require("./error-summary-item.cjs");
const require_error_summary_link = require("./error-summary-link.cjs");
const require_error_summary_list = require("./error-summary-list.cjs");
//#region src/components/error-summary/index.ts
/**
* ErrorSummary component, used to display a list of errors.
*
* @example
* <ErrorSummary>
*   <ErrorSummary.Heading>Heading</ErrorSummary.Heading>
*   <ErrorSummary.List>
*     <ErrorSummary.Item>
*       <ErrorSummary.Link href='#'>Error 1</ErrorSummary.Link>
*     </ErrorSummary.Item>
*     <ErrorSummary.Item>
*       <ErrorSummary.Link href='#'>Error 2</ErrorSummary.Link>
*     </ErrorSummary.Item>
*   </ErrorSummary.List>
* </ErrorSummary>
*/
const ErrorSummaryComponent = Object.assign(require_error_summary.ErrorSummary, {
	Heading: require_error_summary_heading.ErrorSummaryHeading,
	Item: require_error_summary_item.ErrorSummaryItem,
	List: require_error_summary_list.ErrorSummaryList,
	Link: require_error_summary_link.ErrorSummaryLink
});
ErrorSummaryComponent.Item.displayName = "ErrorSummary.Item";
ErrorSummaryComponent.Heading.displayName = "ErrorSummary.Heading";
ErrorSummaryComponent.List.displayName = "ErrorSummary.List";
ErrorSummaryComponent.Link.displayName = "ErrorSummary.Link";
//#endregion
exports.ErrorSummary = ErrorSummaryComponent;
exports.ErrorSummaryHeading = require_error_summary_heading.ErrorSummaryHeading;
exports.ErrorSummaryItem = require_error_summary_item.ErrorSummaryItem;
exports.ErrorSummaryLink = require_error_summary_link.ErrorSummaryLink;
exports.ErrorSummaryList = require_error_summary_list.ErrorSummaryList;
